"""Install the Git pre-commit hook.

    python scripts/install_hook.py

From then on every `git commit` runs `check.py` first and is aborted when
something is broken. Works on Windows, Linux and macOS.

To skip the check for one commit (use sparingly):

    git commit --no-verify -m "wip"
"""

import stat
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

HOOK = """#!/bin/sh
# Generated by scripts/install_hook.py — runs the checks before committing.
echo "Verificando o projeto antes do commit..."
python check.py || {
    echo ""
    echo "Commit abortado: a verificacao falhou."
    echo "Corrija os erros acima, ou use 'git commit --no-verify' para pular."
    exit 1
}
"""


def main() -> int:
    hooks = ROOT / ".git" / "hooks"
    if not hooks.parent.exists():
        print("Erro: este diretório ainda não é um repositório Git.")
        print("Rode 'git init' primeiro.")
        return 1

    hooks.mkdir(parents=True, exist_ok=True)
    target = hooks / "pre-commit"
    target.write_text(HOOK, encoding="utf-8", newline="\n")

    # Executable bit. Git on Windows runs the hook through its own sh and
    # ignores the mode, so this is a no-op there rather than an error.
    target.chmod(target.stat().st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)

    print(f"Hook instalado em {target}")
    print("A partir de agora, todo 'git commit' roda a verificação antes.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
